// Range la fiche de Hunter dans la piece Enquetes du chateau, et la renvoie a Archi
const fs = require('fs');
const fiche = String($input.first().json.output || '').trim();
let requete = '';
try { requete = String($('When Executed by Another Workflow').first().json.requete || ''); } catch (e) {}

let chemin = '';
if (fiche.length > 200 && !/hors de mes règles/i.test(fiche.slice(0, 300))) {
  const sujet = ((fiche.match(/Fiche\s*:\s*([^\n]+)/i) || [])[1] || requete).slice(0, 60);
  const nom = sujet.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'enquete';
  const date = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Paris' });
  const dossier = ($env.ARCHI_BASE || '') + '/memoire/enquetes/';
  fs.mkdirSync(dossier, { recursive: true });
  chemin = dossier + nom + '_' + date + '.md';
  fs.writeFileSync(chemin, '## Enquête du ' + date + '\n**Mission :** ' + requete.slice(0, 500) + '\n\n' + fiche + '\n\n**Liens :**\n- [[Enquêtes]]\n', 'utf8');
}
return [{ json: { output: fiche + (chemin ? '\n\n(Fiche rangée dans le château : enquetes/' + chemin.split('/').pop() + ')' : '') } }];
